package tokenizer

import java.time.format.DateTimeFormatter
import java.time.temporal.Temporal
import java.time.{LocalDate, LocalDateTime}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}
import io.circe.Json

// ============================================================================
// Enums and Constants
// ============================================================================

sealed abstract class TokenType(val value: String)
object TokenType {
  case object STRING extends TokenType("string")
  case object NUMERIC extends TokenType("numeric")
  case object TEMPORAL extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY extends TokenType("binary")
  case object NULL extends TokenType("null")
}

// ============================================================================
// Protocol definitions (Traits in Scala)
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(newMeta: (String, Any)*): Token = {
    copy(metadata = metadata ++ newMeta)
  }
}

class MutableTokenBatch {
  private val tokens = mutable.ListBuffer.empty[Token]
  private var _processed: Boolean = false

  def add(token: Token): Unit = {
    if (_processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def getTokens: List[Token] = tokens.toList
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+T](items: Seq[T]) {
  private val _items: Seq[T] = items

  def getAll: Seq[T] = _items

  def mapTokens(func: T => String): Seq[String] = {
    _items.map(func)
  }

  def size: Int = _items.size
}

class TokenSink[-T] {
  private val _received = mutable.ListBuffer.empty[Any]

  def receive(item: T): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

class BivariantHandler[T](default: T) {
  private var _value: T = default

  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[String] {

  def tokenize(value: String): Token = {
    // In Scala strings are already decoded sequences of chars, 
    // but if we were handling byte arrays we'd decode.
    // Assuming input is String here as per signature.
    val normalized = normalizer(value)
    Token(normalized, TokenType.STRING)
  }

  // Overload for bytes if needed, but BaseTokenizer[String] constrains it.
  def tokenize(value: Array[Byte]): Token = {
     val strValue = new String(value, encoding)
     tokenize(strValue)
  }
}

class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] { // Using Any to cover Int, Double, BigDecimal like Python's Union

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case d: BigDecimal => d.setScale(precision, scala.math.BigDecimal.RoundingMode.HALF_UP).toString()
      case f: Float      => s"%.${precision}f".format(f)
      case d: Double     => s"%.${precision}f".format(d)
      case n: Number     => n.toString
      case other         => other.toString
    }

    Token(
      strValue,
      TokenType.NUMERIC,
      Map("original_type" -> value.getClass.getSimpleName)
    )
  }
}

class TemporalTokenizer(
    formatStr: Option[String] = None
) extends BaseTokenizer[Temporal] {

  private val ISO_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE_TIME
  private val DATE_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE

  override def tokenize(value: Temporal): Token = {
    val formatter = formatStr match {
      case Some(fmt) => DateTimeFormatter.ofPattern(fmt)
      case None => value match {
        case _: LocalDateTime => ISO_FORMAT
        case _: LocalDate => DATE_FORMAT
        case _ => ISO_FORMAT // Fallback
      }
    }

    // TemporalAccessor handling for formatting
    val strValue = try {
      formatter.format(value)
    } catch {
       // Fallback for simple toString if format fails or types mismatch
       case _: Exception => value.toString 
    }

    Token(strValue, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Advanced: Union Types and Overloads
// ============================================================================

class UniversalTokenizer {
  private val _stringTokenizer = new StringTokenizer()
  private val _numericTokenizer = new NumericTokenizer()
  private val _temporalTokenizer = new TemporalTokenizer()

  // Overloaded signatures
  def tokenize(value: String): Token = _stringTokenizer.tokenize(value)
  def tokenize(value: Array[Byte]): Token = _stringTokenizer.tokenize(value)
  def tokenize(value: Int): Token = _numericTokenizer.tokenize(value)
  def tokenize(value: Double): Token = _numericTokenizer.tokenize(value)
  def tokenize(value: BigDecimal): Token = _numericTokenizer.tokenize(value)
  def tokenize(value: Temporal): Token = _temporalTokenizer.tokenize(value)
  def tokenize(value: Tokenizable): Token = Token(value.toToken, TokenType.STRUCTURED)

  // Test helper method for null handling since Scala avoids passing null to methods usually
  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  // Dispatch based on runtime type (Python's tokenize(value: Any))
  def tokenize(value: Any): Token = value match {
